-- Optional: refresh mcore-bkpay-notify + morning to honour pay_settings toggles and deep-link Dashboard inbox.
-- WRITE-ONLY. Run AFTER booking_flow_01.sql. No CREATE FUNCTION. No dollar-quoting.
-- If cron.job missing, statements no-op via WHERE jobname.

-- notify: new receipt + remind; skip when flag false; who = owner or owner_admin; link -> dashboard bkid + bktab proof
update cron.job set command =
  'with c as (update public.payment_claims pc set notified_at = now() where pc.status = ''pending'' and pc.notified_at is null and pc.deleted_at is null and exists (select 1 from public.bookings b where b.tenant_id = pc.tenant_id and b.invoice_id = pc.invoice_id) and coalesce((select ps.bk_n_receipt from public.pay_settings ps where ps.tenant_id = pc.tenant_id), true) returning pc.id, pc.tenant_id, pc.invoice_id, pc.amount) insert into public.notifications (tenant_id, user_id, title, body, category, kind, type, priority, link, ref_table, ref_id) select c.tenant_id, u.id, case when u.language = ''bm'' then ''Resit bayaran tempahan untuk disemak'' else ''Booking payment receipt to review'' end, case when u.language = ''bm'' then concat_ws('' · '', bk.quote_ref, i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Buka Peti Tempahan untuk sahkan.'' else concat_ws('' · '', bk.quote_ref, i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Open Booking Inbox to verify.'' end, ''sales'', ''action'', ''sales.booking_receipt'', 2, jsonb_build_object(''page'', ''dashboard'', ''params'', jsonb_build_object(''bkid'', bk.id::text, ''bktab'', ''proof'', ''claim'', c.id::text)), ''payment_claims'', c.id::text from c join public.invoices i on i.id = c.invoice_id and i.tenant_id = c.tenant_id left join lateral (select b.id, b.quote_ref from public.bookings b where b.tenant_id = c.tenant_id and b.invoice_id = c.invoice_id limit 1) bk on true join public.user_profiles u on u.tenant_id = c.tenant_id and coalesce(u.is_active, true) and lower(coalesce(u.role, '''')) = any (case when coalesce((select ps.bk_n_who from public.pay_settings ps where ps.tenant_id = c.tenant_id), ''owner_admin'') = ''owner'' then array[''owner''] else array[''owner'', ''admin''] end); with c as (update public.payment_claims pc set reminded_at = now() where pc.status = ''pending'' and pc.reminded_at is null and pc.deleted_at is null and exists (select 1 from public.bookings b where b.tenant_id = pc.tenant_id and b.invoice_id = pc.invoice_id) and coalesce((select ps.bk_n_remind from public.pay_settings ps where ps.tenant_id = pc.tenant_id), true) and coalesce((select ps.bk_remind_min from public.pay_settings ps where ps.tenant_id = pc.tenant_id), 30) > 0 and pc.created_at < now() - make_interval(mins => coalesce((select ps.bk_remind_min from public.pay_settings ps where ps.tenant_id = pc.tenant_id), 30)) returning pc.id, pc.tenant_id, pc.invoice_id, pc.amount, pc.created_at) insert into public.notifications (tenant_id, user_id, title, body, category, kind, type, priority, link, ref_table, ref_id) select c.tenant_id, u.id, case when u.language = ''bm'' then ''Resit tempahan masih menunggu semakan'' else ''Booking receipt still waiting for review'' end, case when u.language = ''bm'' then concat_ws('' · '', i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Dihantar '' || to_char(c.created_at at time zone ''Asia/Kuala_Lumpur'', ''HH12:MI AM'') || '' (MYT).'' else concat_ws('' · '', i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Sent '' || to_char(c.created_at at time zone ''Asia/Kuala_Lumpur'', ''HH12:MI AM'') || '' (MYT).'' end, ''sales'', ''action'', ''sales.booking_receipt_remind'', 2, jsonb_build_object(''page'', ''dashboard'', ''params'', jsonb_build_object(''bkid'', bk.id::text, ''bktab'', ''proof'', ''claim'', c.id::text)), ''payment_claims'', c.id::text from c join public.invoices i on i.id = c.invoice_id and i.tenant_id = c.tenant_id left join lateral (select b.id from public.bookings b where b.tenant_id = c.tenant_id and b.invoice_id = c.invoice_id limit 1) bk on true join public.user_profiles u on u.tenant_id = c.tenant_id and coalesce(u.is_active, true) and lower(coalesce(u.role, '''')) = any (case when coalesce((select ps.bk_n_who from public.pay_settings ps where ps.tenant_id = c.tenant_id), ''owner_admin'') = ''owner'' then array[''owner''] else array[''owner'', ''admin''] end);'
where jobname = 'mcore-bkpay-notify';

update cron.job set command =
  'with y as (select ((now() at time zone ''Asia/Kuala_Lumpur'')::date - 1) d), t as (select pc.tenant_id, count(*) filter (where pc.status = ''pending'') np, coalesce(sum(pc.amount) filter (where pc.status = ''pending''), 0) ap, count(*) filter (where pc.status = ''approved'' and (pc.reviewed_at at time zone ''Asia/Kuala_Lumpur'')::date = (select d from y)) nv, coalesce(sum(coalesce(p.amount, pc.amount)) filter (where pc.status = ''approved'' and (pc.reviewed_at at time zone ''Asia/Kuala_Lumpur'')::date = (select d from y)), 0) av, count(*) filter (where pc.status = ''rejected'' and (pc.reviewed_at at time zone ''Asia/Kuala_Lumpur'')::date = (select d from y)) nr from public.payment_claims pc left join public.payments p on p.id = pc.payment_id and p.tenant_id = pc.tenant_id where pc.deleted_at is null and (pc.status = ''pending'' or pc.reviewed_at > now() - interval ''3 days'') and exists (select 1 from public.bookings b where b.tenant_id = pc.tenant_id and b.invoice_id = pc.invoice_id) and coalesce((select ps.bk_n_digest from public.pay_settings ps where ps.tenant_id = pc.tenant_id), true) group by pc.tenant_id) insert into public.notifications (tenant_id, user_id, title, body, category, kind, type, priority, link) select t.tenant_id, u.id, case when u.language = ''bm'' then ''Bayaran tempahan: ringkasan pagi'' else ''Booking payments: morning summary'' end, case when u.language = ''bm'' then t.np || '' menunggu semakan (RM '' || to_char(t.ap, ''FM999,999,990.00'') || '') · '' || t.nv || '' disahkan semalam (RM '' || to_char(t.av, ''FM999,999,990.00'') || '') · '' || t.nr || '' ditolak semalam'' else t.np || '' waiting for review (RM '' || to_char(t.ap, ''FM999,999,990.00'') || '') · '' || t.nv || '' verified yesterday (RM '' || to_char(t.av, ''FM999,999,990.00'') || '') · '' || t.nr || '' rejected yesterday'' end, ''sales'', ''for_you'', ''sales.booking_pay_digest'', case when t.np > 0 then 1 else 0 end, jsonb_build_object(''page'', ''dashboard'', ''params'', jsonb_build_object(''bktab'', ''proof'')) from t join public.user_profiles u on u.tenant_id = t.tenant_id and coalesce(u.is_active, true) and lower(coalesce(u.role, '''')) = any (case when coalesce((select ps.bk_n_who from public.pay_settings ps where ps.tenant_id = t.tenant_id), ''owner_admin'') = ''owner'' then array[''owner''] else array[''owner'', ''admin''] end) where t.np + t.nv + t.nr > 0;'
where jobname = 'mcore-bkpay-morning';
